#!/usr/bin/env node
// Futari worktree lifecycle. Node.js >=22; no dependencies.
// The only code path that creates or removes Futari worktrees. A worktree is removed only when a
// Futari ownership record proves it belongs to this plan and every safety check passes; anything
// else is retained and reported with a reason. Never uses --force, rm -rf, stash, or branch deletion.
//
//   acquire --task P-001 --role worker [--base REV] [--owner LABEL] [--adopt]
//   acquire --task P-001 --role reviewer|adversary --at REV [--owner LABEL]
//   release --id ID --lease N --reason merged|merge-ready|verdict-recorded [--pr N]
//   sweep [--dry-run]        status = sweep --dry-run
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const TASK = /^P-\d{3,}$/;
const ROLES = new Set(['worker', 'reviewer', 'adversary']);
const RELEASE_REASONS = new Set(['merged', 'merge-ready', 'verdict-recorded']);
const RECORD = 'futari.json';
// pstack worktree-audit.mjs DISPOSABLE: an ignored path under one of these names is a rebuildable artifact.
const DISPOSABLE = new Set([
