          throw new Exit(3, { error: 'in-use', id: record.id, session: record.session });
        }
        const lease = (record.lease ?? 0) + 1;
        writeRecord(entry.admin, { ...record, owner, session, lease, state: 'active', releasedAt: null, releaseReason: null });
        return { id: record.id, path: record.path, branch: record.branch, task, role, lease, created: false, recovered: true };
      }
    }
    const id = `${task}-${role}-${crypto.randomBytes(3).toString('hex')}`;
    const parent = path.join(ctx.primary, '.futari', 'worktrees');
    fs.mkdirSync(parent, { recursive: true });
    excludeWorktrees(ctx.common);
    const target = path.join(real(parent), id);
    const record = {
      schemaVersion: 1, id, planId: ctx.planId, task, role, owner, branch, taskBranch: `futari/${task}`, path: target,
      createdAt: new Date().toISOString(), state: 'active', releasedAt: null, releaseReason: null, pr: null, lease: 1, session,
    };
    // Record the intent before creating anything, so a crash in between is adopted by the next command.
    const pending = path.join(ctx.common, 'futari', 'pending', `${id}.json`);
    fs.mkdirSync(path.dirname(pending), { recursive: true });
    fs.writeFileSync(pending, JSON.stringify(record), { flag: 'wx' });
    try {
      if (branch && sh(ctx.primary, 'git', ['show-ref', '--verify', '--quiet', `refs/heads/${branch}`]).status === 0) {
        git(ctx.primary, ['worktree', 'add', target, branch]);
      } else if (branch) {
        git(ctx.primary, ['worktree', 'add', '-b', branch, target, remoteTip || args.base || 'HEAD']);
      } else {
        git(ctx.primary, ['worktree', 'add', '--detach', target, args.at]);
      }
    } catch (error) { fs.unlinkSync(pending); throw new Exit(1, { error: error.message }); }
    writeRecord(git(target, ['rev-parse', '--absolute-git-dir']).trim(), record);
    fs.unlinkSync(pending);
    return { id, path: target, branch, task, role, lease: 1, created: true, recovered: false };
  });
}
function excludeWorktrees(common) {
  const file = path.join(common, 'info', 'exclude');
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  if (!current.split('\n').includes('/.futari/worktrees/')) {
    fs.appendFileSync(file, `${current && !current.endsWith('\n') ? '\n' : ''}/.futari/worktrees/\n`);
  }
}

function release(args) {
  if (!args.id) throw new Exit(1, { error: 'release needs --id' });
  if (!RELEASE_REASONS.has(args.reason)) throw new Exit(1, { error: `--reason must be one of ${[...RELEASE_REASONS].join(', ')}` });
  const pr = args.pr === undefined ? null : Number(args.pr);
  if (pr !== null && !(Number.isInteger(pr) && pr > 0)) throw new Exit(1, { error: '--pr must be a pull request number' });
  const lease = args.lease === undefined ? null : Number(args.lease);
  const session = currentSession();
  prefetchRemote(context(), record => record.id === args.id, pr);
  return withLock(context(), () => {
    const ctx = context();
    const match = owned(ctx).find(({ record }) => record.id === args.id);
    if (!match) return { id: args.id, state: 'gone' };
    const { entry, record } = match;
    if (record.state === 'active' && heldByOther(record.session, session)) throw new Exit(3, { error: 'in-use', id: record.id, session: record.session });
    // A release issued before a later acquire of the same worktree must not remove it from under that acquire.
    if (lease !== null && lease !== (record.lease ?? 1)) throw new Exit(3, { error: 'reacquired', id: record.id, lease: record.lease });
    writeRecord(entry.admin, { ...record, state: 'released', releasedAt: new Date().toISOString(), releaseReason: args.reason, pr: pr ?? record.pr });
    const result = evaluate(entry, context(), true);
    return { id: record.id, state: 'released', removed: result.removed, reasons: result.reasons ?? [] };
  });
}

function parseArgs(argv) {
  const args = { _: [], flags: new Set() };
  for (let i = 0; i < argv.length; i++) {
    const item = argv[i];
    if (!item.startsWith('--')) { args._.push(item); continue; }
    const key = item.slice(2);
    if (['adopt', 'dry-run'].includes(key)) args.flags.add(key);
    else if (argv[i + 1] === undefined || argv[i + 1].startsWith('--')) throw new Exit(1, { error: `Missing value for ${item}` });
    else args[key] = argv[++i];
  }
  return args;
}

export function main(argv = process.argv.slice(2)) {
  const args = parseArgs(argv);
  const command = args._[0];
  if (command === 'acquire') return acquire(args);
  if (command === 'release') return release(args);
  if (command === 'sweep') return sweep(args);
  if (command === 'status') { args.flags.add('dry-run'); return sweep(args); }
  throw new Exit(1, { error: 'usage: worktrees.mjs acquire|release|sweep|status (see header)' });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { console.log(JSON.stringify(main())); }
  catch (error) {
    const exit = error instanceof Exit ? error : new Exit(1, { error: error.message });
    console.log(JSON.stringify(exit.payload));
    console.error(`FUTARI WORKTREES: ${exit.payload.error}`);
    process.exitCode = exit.status;
  }
}
